import React, { useState } from 'react';
import './Product.css';
import PageTitle from '../PageTitle';

function Product() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalContent, setModalContent] = useState('');

  const openModal = (content) => {
    setModalContent(content);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setModalContent('');
  };

  return (
    <>
      <PageTitle title="Ürünümüz" />
      <div className="product-container">
        <div className="product-box">
          <img src="product-image-1.jpg" alt="Ürün 1" className="product-image" />
          <p>Ürün 1 Açıklaması</p>
          <button onClick={() => openModal('Ürün 1 Detayları')}>
            Detayları Göster
          </button>
        </div>
        <div className="product-box">
          <img src="product-image-2.jpg" alt="Ürün 2" className="product-image" />
          <p>Ürün 2 Açıklaması</p>
          <button onClick={() => openModal('Ürün 2 Detayları')}>
            Detayları Göster
          </button>
        </div>
        {/* Diğer ürün kutuları */}
      </div>

      {/* Modal Popup */}
      {isModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h2>Ürün Detayı</h2>
            <p>{modalContent}</p>
            <button onClick={closeModal}>Kapat</button>
          </div>
        </div>
      )}
    </>
  );
}

export default Product;
